(function(){
  'use strict';
  const C=window.StudioCore,D=window.STUDIO_DATA,K=window.CatalogueCore,KEY='em_studio_v1';
  const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
  const today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};
  const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);
  const links={guide:'outputs/gold-standard-2026/Teacher_Guide.html',task:'outputs/gold-standard-2026/Photoshop_Diagnostic.html',ds:'outputs/gold-standard-2026/Digital_Society_Diagnostic.html',prompts:'outputs/gold-standard-2026/Fabrication_Prompts.md',passport:'outputs/gold-standard-2026/Student_Skill_Passport.html',workbook:'outputs/gold-standard-2026/Evidence_Map_and_Skills.xlsx'};
  let state=C.blankState(),loadError='',ctx=null,active='studio',matrix=false,preview=null,sequence='dated',planStatus='all',filter='',skillFilter='',groupDraft=null,assignmentContext=null;
  try{const raw=window.AppStorage.getItem(KEY);if(raw){const x=JSON.parse(raw),e=C.validateState(x,D.skills);if(e.length)loadError=e.join(' ');else state=x;}}catch(e){loadError='Saved studio data could not be read: '+e.message;}
  if(loadError)window.AppStorage.block(loadError);
  function save(next,recovering=false){if(loadError&&!recovering){ctx.toast('Resolve the saved-data error before writing.');return false;}try{window.AppStorage.setItem(KEY,JSON.stringify(next));state=next;loadError='';return true;}catch(e){ctx.toast('Not saved: '+e.message);ctx.recovery();return false;}}
  function mutate(fn){const n=C.clone(state);fn(n);return save(n);}
  function download(content,name,type='text/plain'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
  async function copy(text){try{await navigator.clipboard.writeText(text);ctx.toast('Prompt copied');}catch(e){download(text,'Fabrication_Prompt.txt');ctx.toast('Clipboard unavailable; prompt downloaded');}}
  const students=()=>ctx.students();
  const selected=()=>students().find(x=>x.id===ctx.student())||students()[0];
  const skills=()=>D.skills.filter(x=>x.course===ctx.course()||x.course==='ALL');
  const evidence=()=>C.activeRecords(state.evidence,state).filter(x=>x.course===ctx.course());
  const diagnostics=()=>C.activeRecords(state.diagnostics,state).filter(x=>x.course===ctx.course());
  const latest=(sid,skill)=>evidence().filter(x=>x.student===sid&&x.skill===skill&&x.verified).sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt))[0];
  const readiness=sid=>C.currentReadiness(state,ctx.course(),sid,today());
  const options=(items,value)=>items.map(x=>{const [v,t]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`;}).join('');
  const field=(label,id,html,full=false)=>`<div class="${full?'full':''}"><label for="${id}">${label}</label>${html}</div>`;
  const select=(id,items,value='')=>`<select id="${id}" name="${id}">${options(items,value)}</select>`;
  const textarea=(id,value='',required=false)=>`<textarea id="${id}" name="${id}" ${required?'required':''}>${esc(value)}</textarea>`;
  const input=(id,value='',type='text',required=false)=>`<input id="${id}" name="${id}" value="${esc(value)}" type="${type}" ${required?'required':''}>`;
  const guideLink=(label='Read the teaching guide')=>`<a href="${links.guide}" target="_blank" rel="noopener">${label}</a>`;
  function intro(title,sub){return `<div class="intro"><div><div class="kicker">Evidence Map / ${esc(ctx.course())} / 2026–27</div><h2>${title}</h2><p>${sub}</p></div><div class="actions"><a class="btn ghost" href="help/index.html" target="_blank" rel="noopener">How to use this tool</a><a class="btn ghost" href="outputs/gold-standard-2026/Workbook_Experience/index.html" target="_blank" rel="noopener">Try the demo workbooks</a></div></div>`;}
  function frame(html){$('#areaView').innerHTML=`<div class="studio">${!ctx.isReal()?'<div class="notice warn"><b>Demonstration roster.</b> Import your class roster in Courses before collecting real student evidence. New studio records start blank.</div>':''}${loadError?`<div class="notice warn"><b>Saved data needs attention.</b> ${esc(loadError)} <button class="btn ghost" id="recoverRaw">Download unchanged stored data</button></div>`:''}${html}</div>`;$('#recoverRaw')?.addEventListener('click',()=>download(window.AppStorage.recovery(),'Studio_recovery.json','application/json'));}
  function route(r){ctx.route(r);}
  function allLessons(){const map=new Map(D.lessons.map(l=>[l.id,l]));state.importedLessons.forEach(l=>map.set(l.id,l));return [...map.values()].map(l=>({...l,...state.planEdits[l.id]}));}
  function assignmentPageContext(){return {data:D,course:ctx.course(),outcomes:ctx.outcomes(),lessons:allLessons(),evidence:evidence(),students:students(),frame,intro,lessonHTML,bindLessons,download,csv:C.csv,route,capture(b){assignmentContext=b;route('profile');$('#evidenceForm')?.scrollIntoView({behavior:'smooth'});}};}
  function assignments(){window.AssignmentStudio.render(assignmentPageContext());}
  function sprintOverview(){window.AssignmentStudio.sprints(assignmentPageContext());}
  function openAssignment(id){window.AssignmentStudio.open(id);route('assignments');}
  function lessonAssignments(l){return D.assessments.filter(a=>a.course===l.course&&(K.list(a.lesson_ids).includes(l.id)||K.list(l.assessment_ids).includes(a.id)));}
  function lessonHTML(l,editable=false){
    const status=l.materials_status||l.status||'Planning draft';
    const detail=`${l.builds_on?'<p><b>Builds on:</b> '+esc(l.builds_on)+'</p>':''}${l.new_learning?'<p><b>New learning:</b> '+esc(l.new_learning)+'</p>':''}${l.prepares_for?'<p><b>Prepares for:</b> '+esc(l.prepares_for)+'</p>':''}${l.teacher_model?'<p><b>Teacher model:</b> '+esc(l.teacher_model)+'</p>':''}${l.student_work?'<p><b>Student work:</b> '+esc(l.student_work)+'</p>':''}`;
    const steps=l.build_steps||l.steps||[];
    return `<details><summary>${esc(l.date||'Day '+(l.day||'—'))} · ${esc(l.title)}</summary><div class="lesson-id">${esc(l.id)} · ${esc(l.source||'Supplied plan')}</div><div class="lesson-meta"><span class="pill">${esc(l.minutes||70)} minutes</span><span class="pill">${esc(status)}</span>${l.taught?'<span class="pill">Teacher recorded taught</span>':''}</div>${detail}${l.agenda||l.timing?'<div class="table-wrap"><table><thead><tr><th>Minutes</th><th>Learning</th></tr></thead><tbody>'+(l.agenda||l.timing).map(a=>`<tr><td>${esc(a.minutes)}</td><td>${esc(a.activity||a.action)}</td></tr>`).join('')+'</tbody></table></div>':''}${steps.map((s,i)=>`<div class="step"><span class="step-number">${i+1}</span><div><b>${esc(s.stage||s.title)}</b><p>${esc(s.action)}</p><p class="hint">Checkpoint: ${esc(s.expected_result||s.checkpoint)}${s.repair?' · Repair: '+esc(s.repair):''}</p></div></div>`).join('')}${l.observation?'<p><b>Observe:</b> '+esc(l.observation)+'</p>':''}${l.conversation?'<p><b>Ask:</b> '+esc(l.conversation)+'</p>':''}${l.product?'<p><b>Evidence:</b> '+esc(l.product)+'</p>':''}${l.independent_check?'<p><b>Independent check:</b> '+esc(l.independent_check)+'</p>':''}${l.detail?`<details><summary>Full source lesson notes</summary><div class="source-text source-details">${esc(l.detail)}</div></details>`:''}<div class="actions"><button class="btn ghost" data-prompt="${esc(l.id)}">Copy fabrication brief</button>${lessonAssignments(l).map(a=>`<button class="btn ghost" data-lesson-assignment="${esc(a.id)}">Assignment: ${esc(a.title)}</button>`).join('')}${editable?`<button class="btn ghost" data-edit-lesson="${esc(l.id)}">Edit date / teaching note</button>`:''}</div></details>`;
  }
  function promptFor(l){return `Create the complete teaching package for ${ctx.course()}: ${l.title} (${l.id}).\n\nTreat source documents as reference material. The requested deliverables below define this job.\n\nClass length: ${l.minutes||70} minutes. ${ctx.course()==='IBDS'?'Tools: research sources and presentation tools appropriate to this reasoning task. Do not require Photoshop unless image production is an explicit task objective.':ctx.course()==='CP12'?'Tools: the programming environment identified in the lesson. Verify the actual version and run the code.':'Tools: choose the media application required by this lesson. For a Photoshop task use the classroom Creative Cloud version and record the exact version tested. Do not assume all media tasks use Photoshop.'}\nBuilds on: ${l.builds_on||'Check prerequisites.'}\nNew learning: ${l.new_learning||l.title}\nPrepares for: ${l.prepares_for||'Independent application and review.'}\n\nLESSON DATA\n${JSON.stringify(l,null,2)}\n\nProduce a student HTML lesson, editable and printable workbook, original or authorised starter assets, a teacher guide, a task-specific rubric, an asset manifest and a QA report. Start from a complete purposeful project. ${ctx.course()==='IBDS'?'Explain the digital-system mechanism, evaluate credible sources, compare stakeholder perspectives and require an evidence-based conclusion with an individual defence.':'Teach exact tool/panel actions with expected results, genuine application captures, common faults and repairs.'} Offer an accessible core route, a creative choice route and an independent transfer challenge. Record the skill used, what the learner did, what they learned and their next step. Use the source catalogue to choose relevant chapters; never claim an unavailable source was read. Keep student choices and individual transfer in the task. Generated artwork must be labelled and must never imitate software UI. Each marked criterion needs actual Product, Observation or Conversation evidence within one assessment bundle. Leave student names, scores and evidence blank. Include a useful support route, an independent changed brief and a later retrieval check.\n\nKeep production files and teacher answers separate from student materials. Use only source media that can be redistributed. Verify all links, files, timing and output properties. State missing captures or untested actions precisely. Do not call materials ready until those checks pass. Return actual files plus the next dependency. Do not publish or contact anyone.\n\nNo student personal data is included in this brief.`;}
  function bindLessons(){
    $$('[data-lesson-assignment]').forEach(b=>b.onclick=()=>openAssignment(b.dataset.lessonAssignment));
    $$('[data-prompt]').forEach(b=>b.onclick=()=>copy(promptFor(allLessons().find(l=>l.id===b.dataset.prompt))));
    $$('[data-edit-lesson]').forEach(b=>b.onclick=()=>{
      const l=allLessons().find(x=>x.id===b.dataset.editLesson);
      const p=document.createElement('div');p.className='panel';p.innerHTML=`<form id="lessonEdit"><h3>Edit ${esc(l.id)}</h3><div class="formgrid">${field('Planned date','editDate',input('editDate',l.date||'','date'))}${field('Title','editTitle',input('editTitle',l.title,'text',true))}${field('Teacher scheduling note','editNote',textarea('editNote',l.teacher_note||''),true)}<div class="notice full"><b>Dependency check</b><p>Builds on: ${esc(l.builds_on||'Check prior learning')}. Prepares for: ${esc(l.prepares_for||'Check the next task')}.</p><p>Nearby lessons: ${allLessons().filter(x=>x.course===l.course&&x.sequence===l.sequence&&x.id!==l.id&&(x.day>l.day-2&&x.day<l.day+3)).map(x=>esc((x.date||'Undated')+' '+x.title)).join('; ')||'Check the course sequence manually.'}</p><label class="checkline"><input type="checkbox" id="dependenciesChecked"> I checked prerequisites and downstream dates</label></div><label class="checkline"><input id="editTaught" type="checkbox" ${l.taught?'checked':''}> I have taught this lesson</label></div><p class="hint">Date changes do not change evidence dates or establish learning. Check downstream lessons before moving a project.</p><div class="actions"><button class="btn primary">Save planning edit</button><button type="button" class="btn ghost" id="editCancel">Cancel</button></div></form>`;b.closest('details').append(p);
      $('#editCancel').onclick=()=>p.remove();$('#lessonEdit').onsubmit=e=>{e.preventDefault();if(($('#editDate').value||null)!==(l.date||null)&&!$('#dependenciesChecked').checked){ctx.toast('Review the dependency check before changing the date.');return;}if(mutate(n=>{n.planHistory.push({at:new Date().toISOString(),edits:C.clone(n.planEdits),lessons:C.clone(n.importedLessons)});n.planHistory=n.planHistory.slice(-5);n.planEdits[l.id]={...n.planEdits[l.id],date:$('#editDate').value||null,title:$('#editTitle').value,teacher_note:$('#editNote').value,taught:$('#editTaught').checked};})){ctx.toast('Plan saved; evidence preserved');render(active);}};
    });
  }
  function home(){
    const next=allLessons().filter(l=>l.course===ctx.course()&&l.sequence==='dated'&&(l.date||'')>=today()&&!l.taught).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,5);
    const backlog=allLessons().filter(l=>l.course===ctx.course()&&l.sequence==='dated'&&!l.taught&&(!l.date||l.date<today()));
    const reviewed=students().filter(s=>readiness(s.id).band!==null).length;
    frame(intro('Teach from evidence','Your next classes, current skills and teaching materials in one place. Start with a small individual performance, plan the support, then revisit the skill.')+`<div class="metrics"><div class="metric"><b>${skills().filter(s=>s.course!=='ALL').length}</b><span>course skills + 4 shared habits</span></div><div class="metric"><b>${reviewed} / ${students().length}</b><span>current readiness profiles</span></div><div class="metric"><b>${evidence().filter(x=>x.verified).length}</b><span>verified skill observations</span></div><div class="metric"><b>${D.counts.activeLessons}</b><span>preserved lessons across three courses</span></div></div><div class="grid"><div class="panel"><h3>Build a useful 1–4 profile</h3><p>Use a local criterion score and a private readiness band. Record assistance, keep the previous attempt, and set the next opportunity.</p><div class="actions"><button class="btn primary" id="goDiagnostic">Open diagnostic</button><button class="btn ghost" id="goProfile">Student OS</button></div><p class="hint">Seat numbers identify turns. Readiness numbers describe a current task. Neither is an IB grade or a learning-style label.</p></div><div class="panel"><h3>Make the group work</h3><p>Draft mixed-readiness teams, review every seat, and rotate who explains, operates and checks. Every learner still produces individual evidence.</p><div class="actions"><button class="btn primary" id="goGroups">Plan teams and seats</button>${guideLink()}</div></div></div><div class="panel"><h3>Next five classes</h3>${backlog.length?'<div class="notice warn">'+backlog.length+' untaught lessons have an earlier date or no date. Open Course Plan and use the Earlier / unscheduled filter to reschedule or mark them taught.</div>':''}<p class="hint">Citrus Rush replaces ten matching MM12/COM11 draft lessons. Sneaker and date-neutral alternatives remain in the library. Dates are inherited planning dates; confirm the school timetable.</p>${next.length?next.map(l=>lessonHTML(l,true)).join(''):'<p>No future dated lessons for this course. Open the course plan or adjust dates.</p>'}<div class="actions"><button class="btn ghost" id="goPlan">Open full course plan</button></div></div><div class="notice">${D.counts.sourceEntries} source entries reconciled; ${D.counts.duplicates} exact duplicates identified. Original documents and spreadsheets remain available. <button class="linkbtn" id="goLibrary">Open resource library</button></div>`);
    for(const [id,r] of [['goDiagnostic','diagnostic'],['goProfile','profile'],['goGroups','groups'],['goPlan','courseplan'],['goLibrary','library']])$('#'+id).onclick=()=>route(r);bindLessons();
  }
  function skillPage(){
    const list=skills().filter(s=>!skillFilter||[s.name,s.id,...s.outcome_codes].join(' ').toLowerCase().includes(skillFilter.toLowerCase()));
    let html=intro('Skills and evidence','Track what students can demonstrate, with the task, conditions and a next step. The same skill can be revisited in another project.')+`<div class="actions"><button class="btn ${matrix?'ghost':'primary'}" id="skillList">Skill library</button><button class="btn ${matrix?'primary':'ghost'}" id="skillMatrix">Class evidence map</button><button class="btn ghost" id="evidenceCSV">Export evidence CSV</button></div>${field('Find a skill or outcome code','skillSearch',input('skillSearch',skillFilter))}<div class="panel"><h3>Student skill passports</h3><p class="hint">Import one student export or one combined JSON file for this class. A combined file can contain many students and skills: up to 2,000 claims and 2 MB. Every claim must match the selected course, an exact roster ID and a listed skill. Review once, then import the entire batch; teacher verification stays separate.</p><div class="actions"><a class="btn ghost" href="${links.passport}" target="_blank" rel="noopener">Open student passport</a><label for="claimFile">Import student claims</label><input type="file" id="claimFile" accept=".json,application/json" aria-describedby="claimImportHelp"></div><p class="hint" id="claimImportHelp">Files are read only in this browser. Previously imported claim IDs are skipped. Mixed courses or any invalid claim block the whole batch. <a href="help/Student_Claims_Integration.md" target="_blank" rel="noopener">Workbook JSON format and integration guide</a></p><div id="claimPreview" role="region" aria-label="Student claims import review" aria-live="polite"></div></div>`;
    if(matrix){html+=`<div class="panel"><p class="hint">Latest teacher-verified observation per skill. A blank cell means no verified evidence. A number is a task-specific observation, not an averaged course mark. Click a student to open their profile.</p><div class="table-wrap"><table class="matrix"><thead><tr><th>Student</th>${list.map(s=>`<th><div class="skill-title">${esc(s.name)}</div></th>`).join('')}</tr></thead><tbody>${students().map(s=>`<tr><td><button class="linkbtn" data-student="${esc(s.id)}">${esc(s.name)}</button></td>${list.map(sk=>{const e=latest(s.id,sk.id);return `<td title="${esc(e?e.date+' · '+e.method+' · '+e.note:'No verified evidence')}"><span class="band">${e?.level??'—'}</span></td>`;}).join('')}</tr>`).join('')}</tbody></table></div></div>`;}
    else html+=`<div class="panel">${list.map(s=>`<details><summary>${esc(s.name)} <span class="pill">${esc(s.domain)}</span></summary><div class="lesson-id">${esc(s.id)}</div><p>${esc(s.evidence)}</p><p class="hint">${s.outcome_codes.length?'Proposed '+s.course+' links: '+esc(s.outcome_codes.join(', ')):'Shared habit: keep separate from achievement unless a course criterion explicitly assesses it.'}${s.course==='IBDS'?' Syllabus references are not official assessment criteria.':''}</p><div class="table-wrap"><table><thead><tr>${C.LEVELS.slice(1).map((n,i)=>`<th>${i+1} · ${n}</th>`).join('')}</tr></thead><tbody><tr>${s.descriptors.map(t=>'<td>'+esc(t)+'</td>').join('')}</tr></tbody></table></div><p><b>Next teaching move:</b> ${esc(s.next_step)}</p><button class="btn ghost" data-capture-skill="${s.id}">Record evidence</button></details>`).join('')}</div>`;
    frame(html);$('#skillList').onclick=()=>{matrix=false;skillPage();};$('#skillMatrix').onclick=()=>{matrix=true;skillPage();};$('#skillSearch').onchange=e=>{skillFilter=e.target.value;skillPage();};$('#evidenceCSV').onclick=exportEvidence;
    bindClaimImport();
    $$('[data-student]').forEach(b=>b.onclick=()=>{ctx.setStudent(b.dataset.student);route('profile');});$$('[data-capture-skill]').forEach(b=>b.onclick=()=>{route('profile');$('#evSkill').value=b.dataset.captureSkill;$('#evidenceForm').scrollIntoView({behavior:'smooth'});});
  }
  function evidenceForm(){return `<form id="evidenceForm" class="panel"><h3>Record a skill use</h3>${assignmentContext?`<div class="notice"><b>Assignment: ${esc(assignmentContext.assignment.title)}</b><p>${esc(assignmentContext.assignment.id)} · ${assignmentContext.rubric?'Task rubric linked; review its criteria before judging.':'Task rubric missing. Collect descriptive evidence; do not infer a task mark.'}</p><button class="btn ghost" type="button" id="clearAssignment">Record without this assignment</button></div>`:''}<div class="formgrid">${field('Student','evStudent',select('evStudent',students().map(s=>[s.id,s.name]),selected()?.id))}${field('Skill','evSkill',select('evSkill',skills().map(s=>[s.id,s.name])))}${field('Observed date','evDate',input('evDate',today(),'date',true))}${field('Evidence method','evMethod',select('evMethod',['Product','Observation','Conversation']))}${field('Observed level','evLevel',select('evLevel',[['','Insufficient evidence'],...[1,2,3,4].map(i=>[i,i+' · '+C.LEVELS[i]])]))}${field('Conditions','evSupport',select('evSupport',C.SUPPORT))}${field('Task / attempt ID','evAttempt',input('evAttempt','','text',true))}${field('Artifact location or reference','evArtifact',input('evArtifact'))}${field('What the learner actually did or said','evNote',textarea('evNote','',true),true)}${field('What did the learner learn?','evLearned',textarea('evLearned'),true)}${field('Next step','evNext',input('evNext'),true)}${field('Link this same evidence to an outcome','evOutcome',select('evOutcome',[['','Skill record only'],...ctx.outcomes().map(o=>[o.key,o.code+' · '+o.title])]),true)}${field('Separate teacher outcome judgment','evOutcomeLevel',select('evOutcomeLevel',[['','Evidence link only — no outcome judgment'],...Array.from({length:ctx.outcomeMax()},(_,i)=>[i+1,'Course outcome level '+(i+1)])]),true)}<p class="hint full">The outcome judgment uses the existing course scale (MM12/COM11 1–4; IBDS 1–7) and is separate from the 1–4 skill rating. It is not an IA criterion mark or automatic predicted IB grade. Review the selected outcome and rubric. Shared evidence uses one ID and one artifact reference in both views.</p><label class="checkline full"><input id="evVerified" type="checkbox"> Teacher verified this observation</label></div><div class="actions"><button class="btn primary">Save skill evidence</button><span class="hint">One record documents one skill use. A single product can support several explicitly observed skills.</span></div></form>`;}
  function profile(){
    if(assignmentContext?.assignment.course!==ctx.course())assignmentContext=null;
    const s=selected();if(!s){frame(intro('Student OS','Import a class roster to begin.'));return;}
    const p=state.profiles[ctx.course()+':'+s.id]||{},r=readiness(s.id),ev=evidence().filter(x=>x.student===s.id).sort((a,b)=>b.date.localeCompare(a.date));
    frame(intro('Student OS','A teacher-managed profile for goals, useful supports, skill evidence and reassessment. Export an individual learning summary to share through your usual classroom channel.')+`<div class="grid"><div class="panel"><div class="profile-name">${esc(s.name)}</div><p>${esc(ctx.course())} · ${esc(s.id)}</p><div class="readiness">${r.band??'—'} <span class="pill">${esc(r.status)}</span></div><p class="hint">Current ${ctx.course()==='IBDS'?'case reasoning':'Photoshop'} readiness. ${r.date?'Last reviewed '+esc(r.date)+'. ':''}Review after 42 days or a changed context. This does not authorise tool use.</p><button class="btn ghost" id="shareProfile">Download individual summary</button></div><form class="panel" id="profileForm"><h3>Learning plan</h3>${field('Student goal','profileGoal',input('profileGoal',p.goal||''))}${field('Useful access supports and preferences','profileSupports',textarea('profileSupports',p.supports||''))}${field('Next action and check date','profileNext',textarea('profileNext',p.next||''))}<p class="hint">Record what helps with this task. Avoid fixed learning-style labels, diagnoses or unnecessary personal history.</p><button class="btn primary">Save learning plan</button></form></div>${ctx.legacyHistory().some(c=>c.evidence.length||c.level)?'<div class="panel"><h3>Historical Sound evidence — review before linking</h3><p>Original identifiers and judgments are retained. They have not been transferred to the corrected five-outcome framework.</p>'+ctx.legacyHistory().filter(c=>c.evidence.length||c.level).map(c=>'<details><summary>'+esc(c.key)+' · historical level '+c.level+'</summary>'+c.evidence.map(e=>'<p>'+esc(e.date)+' · '+esc(e.note)+'</p>').join('')+'</details>').join('')+'</div>':''}<div class="panel"><h3>Skill-use dashboard</h3><p class="hint">Practice counts and self-ratings are separate from teacher-verified levels. Open the evidence history to judge growth.</p><div class="table-wrap"><table><thead><tr><th>Skill</th><th>Uses logged</th><th>Latest use</th><th>Latest verified level</th></tr></thead><tbody>${skills().map(sk=>{const uses=ev.filter(e=>e.skill===sk.id);const verified=uses.find(e=>e.verified);return '<tr><td>'+esc(sk.name)+'</td><td>'+uses.length+'</td><td>'+esc(uses[0]?.date||'Not recorded')+'</td><td>'+(verified?.level??'—')+'</td></tr>';}).join('')}</tbody></table></div></div>${evidenceForm()}<div class="panel"><h3>Evidence history</h3>${ev.length?ev.map(x=>`<div class="record"><b>${esc(D.skills.find(s=>s.id===x.skill)?.name||'Outcome evidence')}</b> <span class="pill">${x.level??'No level'} · ${esc(x.method)} · ${esc(x.date)}</span><p>${esc(x.note)}</p>${x.assignmentId?'<p class="hint">Assignment: '+esc(x.assignmentId)+' · Catalogue '+esc(x.catalogueVersion)+'</p>':''}${x.learned?'<p><b>Learning:</b> '+esc(x.learned)+'</p>':''}<p class="hint">${x.verified?'Teacher verified':'Unverified'} · ${esc(x.support)} · Attempt ${esc(x.attempt)} · ${esc(x.artifact||'No artifact reference')}</p><p class="hint">Next: ${esc(x.next||'Set at next conference')}</p>${x.claimId&&!x.verified?`<p class="hint">Student self-rating: ${x.claimedLevel??'Unsure'}. Awaiting inspection.</p><button class="btn ghost" data-review-claim="${esc(x.id)}">Inspect and record teacher evidence</button>`:''}<p class="hint">Evidence ID: ${esc(x.id)}${x.outcomeLinks?.length?' · Linked to '+x.outcomeLinks.map(l=>esc(l.key)).join(', '):''}</p><button class="btn ghost" data-artifact-edit="${esc(x.id)}">Update artifact reference</button><button class="linkbtn danger" data-void="${esc(x.id)}">Correct this record</button></div>`).join(''):'<p>No skill evidence recorded yet.</p>'}</div>`);
    if(assignmentContext){
      $('#evAttempt').value=assignmentContext.assignment.id;
      $('#evOutcome').value='';$('#evOutcomeLevel').value='';
      $('#evOutcomeLevel').disabled=!assignmentContext.rubric;
      if(!assignmentContext.rubric){$('#evOutcomeLevel').title='Task rubric missing. Outcome evidence can be linked without assigning a level.';}
      $('#clearAssignment').onclick=()=>{assignmentContext=null;profile();};
    }
    $('#profileForm').onsubmit=e=>{e.preventDefault();if(mutate(n=>n.profiles[ctx.course()+':'+s.id]={goal:$('#profileGoal').value,supports:$('#profileSupports').value,next:$('#profileNext').value,updatedAt:new Date().toISOString()}))ctx.toast('Learning plan saved');};
    $('#evidenceForm').onsubmit=e=>{e.preventDefault();const record={id:uid(),course:ctx.course(),student:$('#evStudent').value,skill:$('#evSkill').value,date:$('#evDate').value,method:$('#evMethod').value,level:$('#evLevel').value?Number($('#evLevel').value):null,support:$('#evSupport').value,attempt:$('#evAttempt').value.trim(),artifact:$('#evArtifact').value.trim(),note:$('#evNote').value.trim(),next:$('#evNext').value,learned:$('#evLearned').value.trim(),verified:$('#evVerified').checked,createdAt:new Date().toISOString(),demo:!ctx.isReal()};
      if(assignmentContext){record.assignmentId=assignmentContext.assignment.id;record.catalogueVersion=assignmentContext.version;record.rubricId=assignmentContext.rubric?.id||null;}
      if(record.date>today()){ctx.toast('Evidence date cannot be in the future.');return;}record.relatedClaim=$('#evidenceForm').dataset.claim||null;const key=$('#evOutcome').value,ol=$('#evOutcomeLevel').value;if(ol&&assignmentContext&&!assignmentContext.rubric){ctx.toast('The task rubric is missing. Link evidence without a task-based outcome level.');return;}if(ol&&!key){ctx.toast('Choose an outcome before recording its judgment.');return;}if(key&&!record.verified){ctx.toast('Verify the evidence before linking it to an outcome.');return;}if(key)record.outcomeLinks=[{key,level:ol?Number(ol):null,at:new Date().toISOString(),rubricVersion:assignmentContext?.rubric?.id||'Teacher-reviewed outcome at capture'}];const n=C.clone(state);n.evidence.push(record);const err=C.validateState(n,D.skills);if(err.length){ctx.toast(err[0]);return;}if(key?ctx.saveShared(n,{course:record.course,student:record.student,key,id:record.id,level:ol?Number(ol):null}):save(n)){ctx.setStudent(record.student);ctx.toast('Evidence saved');profile();}};
    $$('[data-artifact-edit]').forEach(b=>b.onclick=()=>{const record=state.evidence.find(x=>x.id===b.dataset.artifactEdit);const box=document.createElement('form');box.className='panel';box.innerHTML='<label>Artifact reference <input name="artifact" value="'+esc(record.artifact)+'"></label><button class="btn primary">Save reference revision</button>';b.after(box);box.onsubmit=e=>{e.preventDefault();if(mutate(n=>{const r=n.evidence.find(x=>x.id===record.id);r.revisions=r.revisions||[];r.revisions.push({at:new Date().toISOString(),artifact:r.artifact});r.artifact=box.elements.artifact.value.trim();})){ctx.toast('Shared artifact reference updated; previous reference retained');profile();}};});
    $('#shareProfile').onclick=()=>{const lines=[s.name+' — '+ctx.course()+' learning summary','Goal: '+(p.goal||''),'Next action: '+(p.next||''),'',...ev.filter(x=>x.verified).map(x=>(D.skills.find(s=>s.id===x.skill)?.name||x.skill)+' | '+x.date+' | '+(x.level?C.LEVELS[x.level]:'Evidence collected')+'\n'+x.note+'\nNext: '+(x.next||''))];download(lines.join('\n'),ctx.course()+'-individual-learning-summary.txt');};bindVoids();$$('[data-review-claim]').forEach(b=>b.onclick=()=>{const c=state.evidence.find(x=>x.id===b.dataset.reviewClaim);assignmentContext=K.bundles(D,ctx.course(),ctx.outcomes(),allLessons()).find(a=>a.assignment.id===(c.assignmentId||c.attempt))||null;profile();$('#evSkill').value=c.skill;$('#evStudent').value=c.student;$('#evAttempt').value=c.attempt;$('#evArtifact').value=c.artifact;$('#evNext').value=c.next;$('#evLevel').value='';$('#evVerified').checked=false;$('#evNote').value='';$('#evidenceForm').dataset.claim=c.id;$('#evNote').placeholder='Inspect the work, then write what you observed. The original student claim stays in the history.';$('#evidenceForm').scrollIntoView({behavior:'smooth'});});
  }
  function bindVoids(){ $$('[data-void]').forEach(b=>b.onclick=()=>{const reason=window.prompt('Why is this record being corrected? The original will remain in the backup history.');if(reason?.trim()&&mutate(n=>n.voids.push({record:b.dataset.void,reason:reason.trim(),date:new Date().toISOString()})))render(active);});}
  function diagnostic(){
    if(ctx.course()==='CP12'){frame(intro('Diagnostic','The new diagnostic is designed for MM12, COM11 and Digital Society. Select one of those courses.'));return;}
    const ds=ctx.course()==='IBDS',rubric=D.diagnosticRubrics[ds?'DS':'PS'],attempts=diagnostics().filter(d=>d.student===selected()?.id).sort((a,b)=>b.date.localeCompare(a.date));
    frame(intro(ds?'Digital Society readiness':'Photoshop readiness','A short individual task establishes a starting point. Teach the next step and return with an equivalent changed task. Keep the full criterion profile alongside the number.')+`<div class="notice"><b>Local diagnostic, informed by Kagan grouping principles.</b> This is not a validated Kagan assessment. The task score is 4–16 only when all four criteria are observed. The suggested band uses the lowest core criterion; the teacher records the final band and a reason. Missing evidence is blank.</div><div class="actions"><a class="btn primary" href="${ds?links.ds:links.task}" target="_blank" rel="noopener">Open task and retest</a>${guideLink()}<button class="btn ghost" id="diagnosticsCSV">Export diagnostic CSV</button></div><div class="panel"><details><summary>Scoring anchors and support rules</summary><div class="table-wrap"><table><thead><tr><th>Criterion</th>${C.LEVELS.slice(1).map((x,i)=>'<th>'+(i+1)+' · '+x+'</th>').join('')}</tr></thead><tbody>${rubric.map(r=>`<tr><th>${esc(r.name)}</th>${r.bands.map(t=>'<td>'+esc(t)+'</td>').join('')}</tr>`).join('')}</tbody></table></div><p class="hint">Approved access supports do not lower the band. Instructional hints or modelling limit this attempt to a provisional 1 or 2; collect another independent performance before 3 or 4. Two independent dates strengthen the profile; they do not certify an ability.</p></details></div><form class="panel" id="diagnosticForm"><h3>Record an attempt</h3><div class="formgrid">${field('Student','diagStudent',select('diagStudent',students().map(s=>[s.id,s.name]),selected()?.id))}${field('Task version','diagTask',select('diagTask',ds?['DS-A','DS-B']:['PS-A','PS-B']))}${field('Assessment date','diagDate',input('diagDate',today(),'date',true))}${field('Instructional conditions','diagSupport',select('diagSupport',C.SUPPORT))}${rubric.map((r,i)=>field(r.name,'rating'+i,select('rating'+i,[['','Not observed'],...[1,2,3,4].map(n=>[n,n+' · '+C.LEVELS[n]])]))).join('')}${field('Artifact / attempt reference','diagArtifact',input('diagArtifact'))}${field('Access supports provided','diagAccess',input('diagAccess'))}${field('Specific live action observed','diagObservation',textarea('diagObservation'),true)}${field('Individual explanation / changed-condition response','diagExplanation',textarea('diagExplanation'),true)}</div><div class="inline-result" id="diagResult" aria-live="polite"></div><div class="formgrid">${field('Teacher readiness band','diagBand',select('diagBand',[['','Do not assign yet'],...[1,2,3,4].map(n=>[n,n+' · '+C.LEVELS[n]])]))}${field('Next review date','diagReview',input('diagReview','','date'))}${field('Reason for the teacher band and next teaching action','diagRationale',textarea('diagRationale'),true)}<label class="checkline full"><input id="diagVerified" type="checkbox"> I verified the individual evidence and the assessment conditions</label></div><div class="actions"><button class="btn primary">Save attempt</button><span id="diagError" class="error" role="alert"></span></div></form><div class="panel"><h3>Previous attempts for ${esc(selected()?.name||'this student')}</h3>${attempts.length?attempts.map(a=>{const v=C.diagnosticResult(a);return `<div class="record"><b>${esc(a.task)} · ${esc(a.date)}</b> <span class="pill">${v.total??'—'} / 16</span> <span class="pill">Teacher band ${a.teacherBand??'—'}</span><p>Profile: ${a.ratings.map(v=>v??'—').join(' · ')}. ${esc(a.rationale||'No judgement yet.')}</p><p class="hint">${esc(a.support)} · ${a.verified?'Verified':'Unverified'} · ${esc(a.artifact)}</p><button class="linkbtn danger" data-void="${esc(a.id)}">Correct this record</button></div>`;}).join(''):'<p>No attempts yet. Prior attempts will remain here after reassessment.</p>'}</div>`);
    const get=()=>({id:uid(),course:ctx.course(),student:$('#diagStudent').value,task:$('#diagTask').value,date:$('#diagDate').value,ratings:rubric.map((_,i)=>$('#rating'+i).value?Number($('#rating'+i).value):null),support:$('#diagSupport').value,access:$('#diagAccess').value,artifact:$('#diagArtifact').value.trim(),observation:$('#diagObservation').value.trim(),explanation:$('#diagExplanation').value.trim(),teacherBand:$('#diagBand').value?Number($('#diagBand').value):null,rationale:$('#diagRationale').value.trim(),reviewDate:$('#diagReview').value||null,verified:$('#diagVerified').checked,createdAt:new Date().toISOString(),demo:!ctx.isReal()});
    const result=()=>{const r=C.diagnosticResult(get());$('#diagResult').innerHTML=`<div><span class="hint">Task score</span><br><strong>${r.total??'—'} / 16</strong></div><div><span class="hint">Suggested readiness</span><br><strong>${r.suggested??'—'}</strong></div><span class="hint">${esc(r.reason)}</span>`;};$('#diagnosticForm').oninput=result;result();
    $('#diagnosticForm').onsubmit=e=>{e.preventDefault();const rec=get();if(rec.date>today()){$('#diagError').textContent='Assessment date cannot be in the future.';return;}const n=C.clone(state);n.diagnostics.push(rec);const errors=C.validateState(n,D.skills);if(errors.length){$('#diagError').textContent=errors.join(' ');return;}if(save(n)){ctx.setStudent(rec.student);ctx.toast('Attempt saved; prior evidence retained');diagnostic();}};$('#diagnosticsCSV').onclick=exportDiagnostics;bindVoids();
  }
  function groups(){
    const existing=groupDraft||state.groups[ctx.course()],roster=students(),lookup=Object.fromEntries(roster.map(s=>[s.id,s]));
    frame(intro('Teams and seating','Use the current course readiness as one planning input. Review access, relationships and task needs yourself, then share a seating view with names and seat numbers only.')+`<div class="notice">A draft is a starting arrangement. A blank readiness profile is kept as unknown. No learner is automatically labelled “low” because they are new, absent or not yet assessed. Rotate production and explanation roles within teams.</div><div class="panel"><h3>Students present for this activity</h3><div class="students-check">${roster.map(s=>`<label class="checkline"><input type="checkbox" name="groupStudent" value="${esc(s.id)}" checked>${esc(s.name)}</label>`).join('')}</div><div class="actions"><button class="btn primary" id="generateTeams">Draft mixed teams</button><button class="btn ghost" id="clearDraft">Show saved plan</button></div><p class="hint">Teams are generally 3–5 students. Use two active pairs in a team of four. A trio rotates operator, coach and checker after each turn.</p></div>${existing?`<div class="panel"><h3>Review the arrangement</h3><p class="hint">${esc(existing.date||today())} · ${existing.teams.flat().length} students. Readiness is private. Positions 1–4 are seat identifiers, unrelated to readiness bands.</p><div class="team-grid">${existing.teams.map((t,i)=>`<div class="team"><h3>Team ${i+1}</h3><div class="seats">${t.map((id,j)=>{const r=readiness(id);return `<div class="seat"><small>Seat ${j+1}</small><strong>${esc(lookup[id]?.name||'Roster changed: '+id)}</strong><small>Readiness ${r.band??'unknown'} · ${esc(r.status)}</small></div>`;}).join('')}</div></div>`).join('')}</div><div class="formgrid" style="margin-top:18px">${field('First student to swap','swapA',select('swapA',existing.teams.flatMap((t,i)=>t.map((id,j)=>[i+':'+j,lookup[id]?.name||id]))))}${field('Second student to swap','swapB',select('swapB',existing.teams.flatMap((t,i)=>t.map((id,j)=>[i+':'+j,lookup[id]?.name||id]))))}${field('Private review note and activity purpose','groupNote',textarea('groupNote',existing.note||''),true)}</div><div class="actions"><button class="btn ghost" id="swapSeats">Swap seats</button><button class="btn primary" id="saveTeams">Save reviewed plan</button><button class="btn ghost" id="studentSeating">Download student seating view</button></div><p class="hint">The student file includes names, teams, seats and the role routine. It contains no scores, support notes or roster metadata. Check the names before displaying it.</p></div>`:''}`);
    $('#generateTeams').onclick=()=>{const included=new Set($$('input[name=groupStudent]:checked').map(x=>x.value));const present=roster.filter(s=>included.has(s.id)).map(s=>({...s,band:readiness(s.id).band}));if(!present.length){ctx.toast('Select at least one student.');return;}groupDraft={teams:C.makeTeams(present),date:today(),note:'',basis:ctx.course()==='IBDS'?'Case reasoning':'Photoshop',reviewed:false};groups();};$('#clearDraft').onclick=()=>{groupDraft=null;groups();};
    if(existing){$('#swapSeats').onclick=()=>{groupDraft={...existing,note:$('#groupNote').value,reviewed:false,teams:C.swap(existing.teams,$('#swapA').value.split(':').map(Number),$('#swapB').value.split(':').map(Number))};groups();};$('#saveTeams').onclick=()=>{if(existing.teams.flat().some(id=>!lookup[id])){ctx.toast('Roster changed. Create a new draft before saving.');return;}if(mutate(n=>n.groups[ctx.course()]={...existing,note:$('#groupNote').value,reviewed:true,date:today()})){groupDraft=null;ctx.toast('Reviewed seating saved');groups();}};$('#studentSeating').onclick=()=>{if(!existing.reviewed){ctx.toast('Save your reviewed arrangement first.');return;}if(existing.teams.flat().some(id=>!lookup[id])){ctx.toast('Roster changed. Create and review a new plan.');return;}const h=`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Our teams</title><style>body{font:18px/1.5 system-ui;margin:40px;color:#172735}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:24px}section{border:2px solid #647d8a;border-radius:12px;padding:20px;break-inside:avoid}.seats{display:grid;grid-template-columns:1fr 1fr;gap:12px}.seat{padding:14px;background:#edf3f4;border-radius:8px}small{display:block}button{padding:12px}@media print{button{display:none}}</style><h1>Our teams</h1><p>Seat numbers organise turns. Each learner makes and explains their own work.</p><main>${existing.teams.map((t,i)=>`<section><h2>Team ${i+1}</h2><div class="seats">${t.map((id,j)=>`<div class="seat"><small>Seat ${j+1}</small>${esc(lookup[id].name)}</div>`).join('')}</div></section>`).join('')}</main><p>Think first. Take equal turns. Coach with questions. Switch roles. Finish with your own explanation.</p></html>`;download(h,ctx.course()+'-student-seating.html','text/html');};}
  }
  function coursePlan(){
    const lessons=allLessons().filter(l=>l.course===ctx.course()&&(l.sequence||'imported')===sequence&&(planStatus==='all'||planStatus==='backlog'&&!l.taught&&(!l.date||l.date<today())||planStatus==='future'&&!l.taught&&l.date>=today())&&(!filter||[l.title,l.id,l.new_learning].join(' ').toLowerCase().includes(filter.toLowerCase())));
    frame(intro('Course plan and production','The dated plan is the working sequence. Other versions remain available for comparison. A planned assessment is an opportunity to collect evidence; it does not establish achievement.')+`<div class="formgrid">${field('Plan version','planSequence',select('planSequence',[['dated','Dated plan + Citrus revision'],['architecture','Date-neutral Course System v2'],['sneaker','Alternative sneaker campaign'],['imported','Imported lesson proposals']],sequence))}${field('Teaching status','planStatus',select('planStatus',[['all','All lessons'],['backlog','Earlier / unscheduled and untaught'],['future','Future and untaught']],planStatus))}${field('Find a lesson','planSearch',input('planSearch',filter))}</div><div class="notice warn">The current Sound register uses five published outcomes. Original Sound evidence remains available for teacher review. Shared skill/outcome records now use one evidence ID. IB learning targets are local interpretations with official guide references. ${guideLink('Read the reconciliation decisions')}.</div><div class="panel"><h3>${lessons.length} lessons</h3>${lessons.map(l=>lessonHTML(l,true)).join('')||'<p>No lessons in this version for the selected course.</p>'}</div><div class="panel"><h3>Preview a planning import</h3><p class="hint">Accepts Course_System.json, Studio_Revision.json and Advertising_Sprint.json. Imports lesson content only. It cannot add student evidence or marks. Existing teacher edits are preserved.</p><input id="planFile" type="file" accept=".json"><div id="planPreview"></div><div class="actions"><button class="btn ghost" id="rollbackPlan" ${state.planHistory.length?'':'disabled'}>Undo last planning change</button></div></div>`);
    $('#planStatus').onchange=e=>{planStatus=e.target.value;coursePlan();};$('#planSequence').onchange=e=>{sequence=e.target.value;coursePlan();};$('#planSearch').onchange=e=>{filter=e.target.value;coursePlan();};bindLessons();
    $('#planFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>5e6){ctx.toast('Plan file is too large.');return;}try{preview=C.planPreview(JSON.parse(await f.text()),allLessons());showPreview();}catch(err){$('#planPreview').textContent='Cannot read this plan: '+err.message;}};
    $('#rollbackPlan').onclick=()=>{if(mutate(n=>{const p=n.planHistory.pop();n.planEdits=p.edits;n.importedLessons=p.lessons;})){ctx.toast('Last plan change undone');coursePlan();}};
  }
  function showPreview(){const p=$('#planPreview');p.innerHTML=preview.errors.length?'<p class="error">'+preview.errors.map(esc).join('<br>')+'</p>':`<p>${preview.rows.length} lesson records. ${esc(preview.warnings.join(' '))}</p><div class="table-wrap"><table><thead><tr><th>ID</th><th>Existing</th><th>Proposed</th><th>Teacher edit</th></tr></thead><tbody>${preview.rows.map(l=>`<tr><td>${esc(l.id)}</td><td>${esc(l.priorTitle)}</td><td>${esc(l.title)}</td><td>${state.planEdits[l.id]?'Preserved':'None'}</td></tr>`).join('')}</tbody></table></div><button class="btn primary" id="applyPlan">Apply these lesson proposals</button>`;$('#applyPlan')?.addEventListener('click',()=>{if(mutate(n=>{n.planHistory.push({at:new Date().toISOString(),edits:C.clone(n.planEdits),lessons:C.clone(n.importedLessons)});n.planHistory=n.planHistory.slice(-5);const m=new Map(n.importedLessons.map(l=>[l.id,l]));preview.rows.forEach(l=>m.set(l.id,{...l,sequence:allLessons().find(x=>x.id===l.id)?.sequence||'imported',materials_status:'Imported draft; review materials'}));n.importedLessons=[...m.values()];})){preview=null;ctx.toast('Planning lessons merged; student records untouched');coursePlan();}});}
  function bindClaimImport(){
    const fileInput=$('#claimFile'),target=$('#claimPreview'),course=ctx.course();
    let request=0;
    const current=token=>token===request&&target.isConnected&&ctx.course()===course;
    const validate=payload=>{
      const p=C.claimPreview(payload,D.skills,students(),course,state.evidence);
      if(p.rows.some(c=>c.date>today()))p.errors.push('A skill-use date cannot be in the future.');
      return p;
    };
    fileInput.onchange=async e=>{
      const token=++request,f=e.target.files[0];target.replaceChildren();if(!f)return;
      if(f.size>2e6){target.textContent='Choose a passport or combined claims file no larger than 2 MB.';return;}
      target.textContent='Checking claims…';
      try{
        const payload=JSON.parse(await f.text());if(!current(token))return;
        const p=validate(payload);
        if(p.errors.length){target.textContent='Import blocked: '+p.errors.join(' ');return;}
        target.innerHTML=`<p>${p.rows.length} new student claims for ${new Set(p.rows.map(c=>c.student)).size} students in ${esc(course)}; ${p.duplicates} already imported. All enter unverified with no teacher level.</p><div class="table-wrap"><table><thead><tr><th>Student ID</th><th>Skill</th><th>Date</th><th>Claim</th><th>Self-rating</th></tr></thead><tbody>${p.rows.map(c=>`<tr><td>${esc(c.student)}</td><td>${esc(c.skill)}</td><td>${esc(c.date)}</td><td>${esc(c.note)}</td><td>${c.selfRating??'Unsure'}</td></tr>`).join('')}</tbody></table></div><button class="btn primary" id="applyClaims" ${p.rows.length?'':'disabled'}>Import these unverified claims</button>`;
        $('#applyClaims').onclick=()=>{
          if(!current(token))return;
          // Recheck against current evidence and roster before the existing atomic save.
          const latest=validate(payload);
          if(latest.errors.length){target.textContent='Import blocked: '+latest.errors.join(' ');return;}
          if(!latest.rows.length){target.textContent='All claims in this file have already been imported.';return;}
          if(mutate(n=>latest.rows.forEach(c=>n.evidence.push({id:uid(),claimId:c.id,course:c.course,student:c.student,skill:c.skill,date:c.date,method:'Product',level:null,claimedLevel:c.selfRating,support:c.support,attempt:c.attempt,artifact:c.artifact,note:c.note,learned:c.learned||'',next:c.next,verified:false,createdAt:new Date().toISOString(),demo:!ctx.isReal()})))){
            request++;ctx.toast('Student claims imported for inspection');skillPage();
            $('#claimPreview').textContent=`Imported ${latest.rows.length} claims for ${new Set(latest.rows.map(c=>c.student)).size} students in ${course}. Skipped ${latest.duplicates} already imported. Saved in this browser; awaiting teacher inspection.`;
          }
        };
      }catch(err){if(current(token))target.textContent='Import blocked: '+err.message;}
    };
  }
  function exportEvidence(){download(C.csv([['id','course','student','skill','date','method','level','support','attempt','artifact','note','learned','next','verified','assignmentId','catalogueVersion','rubricId'],...evidence().map(e=>['id','course','student','skill','date','method','level','support','attempt','artifact','note','learned','next','verified','assignmentId','catalogueVersion','rubricId'].map(k=>e[k]))]),ctx.course()+'-skill-evidence.csv','text/csv');}
  function exportDiagnostics(){download(C.csv([['id','course','student','task','date','criterion1','criterion2','criterion3','criterion4','task_score_16','suggested_band','teacher_band','support','access','artifact','observation','explanation','rationale','verified'],...diagnostics().map(d=>{const r=C.diagnosticResult(d);return [d.id,d.course,d.student,d.task,d.date,...d.ratings,r.total,r.suggested,d.teacherBand,d.support,d.access,d.artifact,d.observation,d.explanation,d.rationale,d.verified];})]),ctx.course()+'-diagnostics.csv','text/csv');}
  function library(){
    frame(intro('Resource library','One place for the workbooks, diagnostic tasks, research, source decisions and production briefs. Start with the complete fictional demo or the guided practice workbook. Original Excel references are preserved.')+`<div class="grid"><div class="download-card"><a href="outputs/gold-standard-2026/Workbook_Experience/index.html" target="_blank" rel="noopener">Complete demo + practice workbook</a><p>Visual dashboards, 20 fictional learners, linked evidence, benchmark growth, support recommendations and seating. Includes a guided walkthrough.</p></div><div class="download-card"><a href="${links.workbook}" download>Evidence Map and Skills · Excel</a><p>Blank student registers, skill library, diagnostic scores, review profiles, planning and source links.</p></div><div class="download-card"><a href="${links.guide}" target="_blank" rel="noopener">Teacher guide and Kagan research</a><p>Grouping rules, score interpretation, a five-class pilot and source reconciliation.</p></div><div class="download-card"><a href="${links.task}" target="_blank" rel="noopener">Photoshop diagnostic and retest</a><p>Individual performance, teacher rubric and actual starter materials.</p></div><div class="download-card"><a href="${links.ds}" target="_blank" rel="noopener">Digital Society diagnostic</a><p>A reasoning task for Digital Society; Photoshop skill does not determine DS readiness.</p></div><div class="download-card"><a href="${links.passport}" download>Individual student skill passport</a><p>A standalone private learner log with evidence links, self-reflection and JSON export for teacher review.</p></div><div class="download-card"><a href="${links.prompts}" download>Reusable fabrication prompts</a><p>Paste-ready briefs for workbooks, Photoshop assets, lessons and review.</p></div><div class="download-card"><a href="outputs/gold-standard-2026/Consolidated_Course_Data.json" download>Consolidated planning data</a><p>The reviewed content catalogue. Contains no student records. Not a browser-state backup.</p></div></div><div class="panel"><h3>Creative Photoshop resources</h3><p><a href="outputs/gold-standard-2026/Creative_Photoshop_Library.html" target="_blank" rel="noopener">Open the creative library</a>: twelve original project briefs, source checks, guided and independent routes, and a copyable fabrication prompt.</p><p><a href="outputs/gold-standard-2026/Photoshop_Pilot_Checklist.html" target="_blank" rel="noopener">Photoshop exemplars and classroom moderation checklist</a></p><h3>Release files</h3><div class="actions"><a class="btn ghost" href="outputs/gold-standard-2026/START_HERE.html" target="_blank" rel="noopener">Release start page</a><a class="btn ghost" href="outputs/Evidence_Map_Release.zip" download>Download complete release ZIP</a><a class="btn ghost" href="outputs/gold-standard-2026/Student_Kit/START_HERE.html" target="_blank" rel="noopener">Student distribution kit</a><a class="btn ghost" href="outputs/gold-standard-2026/QA_Report.md" target="_blank" rel="noopener">Checks and remaining limits</a></div></div><div class="panel"><h3>Backup your working data</h3><p class="hint">Student records stay in this browser. Excel and CSV are snapshots, not live sync. Studio backup includes skills, profiles, diagnostics, groups and planning edits. Use the app’s full JSON backup to include legacy outcome evidence too.</p><div class="actions"><button class="btn primary" id="studioBackup">Download studio backup</button><button class="btn ghost" id="fullBackup">Download full app backup</button><button class="btn ghost" id="studioRestore">Restore studio backup</button><input id="studioFile" type="file" accept=".json" hidden></div><div id="restorePreview"></div></div><div class="panel"><h3>Original Excel workbooks</h3>${D.files.filter(x=>x.kind==='Original Excel reference').map(f=>`<div class="source-card"><div><p><a href="${esc(f.path)}" download>${esc(f.name)}</a></p><p class="hint">${esc(f.note)}</p></div></div>`).join('')}</div><div class="panel"><h3>Research and current documentation</h3>${D.research.map(s=>`<div class="record"><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)}</a><p class="hint">${esc(s.use)}</p></div>`).join('')}</div><div class="panel"><h3>Source reconciliation</h3><p><a href="help/Curriculum_Reconciliation.json" download>Reviewed Sound crosswalk and IB target register</a>. Five published Sound outcomes use stable new identifiers; historical Sound evidence remains in Student OS for review. IB targets are explicitly local teaching statements with guide references.</p><h3>Source decisions</h3><p><a href="outputs/gold-standard-2026/Source_Archive/INDEX.html" target="_blank" rel="noopener">Open the preserved source archive</a> · Original planning JSON, CSV, HTML, notes and research document.</p><p>95 entries · 55 distinct files · 40 exact duplicates. The Citrus revision matches the dated lesson IDs. The sneaker campaign remains an alternative. The date-neutral architecture provides course direction, not proof that materials are fabricated.</p><a href="outputs/gold-standard-2026/Source_Manifest.json" download>Download complete source manifest</a><details><summary>Preserved source notes and prompts</summary>${D.files.filter(x=>x.kind==='Source notes').map(f=>`<p><a href="${esc(f.path)}" download>${esc(f.name)}</a></p>`).join('')}</details></div>`);
    $('#studioBackup').onclick=()=>download(JSON.stringify({app:'evidence-map-studio',exportedAt:new Date().toISOString(),state},null,2),'Evidence_Map_Studio_Backup.json','application/json');$('#fullBackup').onclick=ctx.backup;$('#studioRestore').onclick=()=>$('#studioFile').click();
    $('#studioFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>10e6){ctx.toast('Backup exceeds the 10 MB limit.');return;}try{const b=JSON.parse(await f.text());if(b.app!=='evidence-map-studio')throw Error('Choose a studio backup, not a planning file.');const errors=C.validateState(b.state,D.skills);if(errors.length)throw Error(errors.join(' '));$('#restorePreview').innerHTML=`<div class="notice warn">Restore ${b.state.evidence.length} skill records and ${b.state.diagnostics.length} diagnostic attempts? This replaces this browser’s studio records. Legacy outcome evidence and rosters stay unchanged. Download the current backup first.</div><div class="actions"><button class="btn primary" id="confirmRestore">Replace studio data with this backup</button><button class="btn ghost" id="cancelRestore">Cancel</button></div>`;$('#confirmRestore').onclick=()=>{const conflict=ctx.canRestoreStudio(b.state);if(conflict){$('#restorePreview').textContent=conflict;return;}if(save(b.state,true)){groupDraft=null;ctx.toast('Studio backup restored');library();}};$('#cancelRestore').onclick=()=>$('#restorePreview').replaceChildren();}catch(err){$('#restorePreview').textContent='Restore blocked: '+err.message;}};
  }
  function render(r){if(r!=='profile')assignmentContext=null;active=r;({studio:home,assignments,sprintoverview:sprintOverview,skills:skillPage,profile,diagnostic,groups,courseplan:coursePlan,library}[r]||home)();}
  window.EvidenceStudio={mount(context){ctx=context;},render,exportState:()=>C.clone(state),resolveEvidence(id){const e=C.activeRecords(state.evidence,state).find(x=>x.id===id);return e?{f:({Product:'Pro',Observation:'Obs',Conversation:'Con'})[e.method],note:e.note+(e.artifact?' · Artifact: '+e.artifact:'')+(e.learned?' · Learning: '+e.learned:'')+' · Shared evidence '+e.id,date:e.date,level:e.level,sharedId:e.id}:null;},validateState:x=>C.validateState(x,D.skills),restoreState:x=>save(x,true),acceptState(x){state=C.clone(x);loadError="";groupDraft=null;},resetView(){groupDraft=null;assignmentContext=null;window.AssignmentStudio.reset();}};
})();
